<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { mentorAPI } from '../../api/mentor'
import type { Application, Organization, Project, ProjectUsage } from '../../api/types'
import { APIError } from '../../api/client'
import StatusBadge from '../../components/StatusBadge.vue'
import AppDialog from '../../components/AppDialog.vue'
import LoadingRegion from '../../components/LoadingRegion.vue'
import CreditDonut from '../../components/CreditDonut.vue'
import { useLoadState } from '../../composables/useLoadState'
import { useToast } from '../../composables/useToast'
const orgs=ref<Organization[]>([]),groups=ref<Array<{org:Organization;projects:Project[]}>>([]),applications=ref<Application[]>([]),activeProject=ref<Project|null>(null),projectUsage=ref<ProjectUsage|null>(null),quotaKey=ref<{id:string;name:string;quota:string}|null>(null),revokeKey=ref<{id:string;name:string}|null>(null),quota=ref(''),reason=ref(''),month=ref(new Date().toISOString().slice(0,7)),error=ref(''),toast=useToast(),loadState=useLoadState(),usageLoadState=useLoadState()
async function load(){await loadState.run(async()=>{try{orgs.value=await mentorAPI.organizations();groups.value=await Promise.all(orgs.value.map(async org=>({org,projects:await mentorAPI.projects(org.id)})));applications.value=await mentorAPI.applications();error.value=''}catch(e){error.value=msg(e)}})}
async function apply(project:Project){try{await mentorAPI.apply(project.id);toast.success('项目申请已提交');await load()}catch(e){error.value=msg(e)}}
async function showUsage(project:Project){activeProject.value=project;await usageLoadState.run(async()=>{try{projectUsage.value=await mentorAPI.usage(project.id,month.value);error.value=''}catch(e){error.value=msg(e)}})}
async function adjustQuota(){if(!quotaKey.value||!reason.value.trim())return;try{await mentorAPI.updateQuota(quotaKey.value.id,quota.value,reason.value);toast.success('Key 月额度已调整');quotaKey.value=null;reason.value='';await showUsage(activeProject.value!)}catch(e){error.value=msg(e)}}
async function revoke(){if(!revokeKey.value||!reason.value.trim())return;try{await mentorAPI.revoke(revokeKey.value.id,reason.value);toast.success('密钥已撤销并立即失效');revokeKey.value=null;reason.value='';await showUsage(activeProject.value!)}catch(e){error.value=msg(e)}}
function percent(used:string,quotaValue:string){return Number(quotaValue)===0?null:Number(used)/Number(quotaValue)*100}
function percentLabel(used:string,quotaValue:string){const value=percent(used,quotaValue);return value===null?'N/A':`${value.toFixed(1)}%`}
function msg(e:unknown){return e instanceof APIError?e.message:'请求失败'}
onMounted(load)
</script>
<template><section class="page"><div class="page-heading"><div><p class="eyebrow">MENTOR</p><h1>项目管理</h1></div><button class="button secondary" @click="load">刷新</button></div><p v-if="error" class="error banner">{{error}}</p><LoadingRegion :initial-loading="loadState.initialLoading.value" :refreshing="loadState.refreshing.value" variant="split" label="正在加载项目和申请"><section v-for="group in groups" :key="group.org.id" class="panel" style="margin-bottom:20px"><h2>{{group.org.name}}</h2><div class="grid two"><article v-for="project in group.projects" :key="project.id" class="panel"><div class="row"><strong>{{project.name}}</strong><StatusBadge :status="project.status"/></div><p class="muted">{{project.description||'暂无说明'}} · 月额度 {{project.monthly_credit_quota}}</p><button v-if="project.is_responsible" class="button ghost" @click="showUsage(project)">项目用量</button><button v-else class="button primary" :disabled="project.status!=='active'||project.application_status==='pending'" @click="apply(project)">{{project.application_status==='pending'?'审核中':'申请负责'}}</button></article></div></section><section class="panel"><h2>申请历史</h2><article v-for="item in applications" :key="item.id" class="list-row"><strong>{{item.project.name}}</strong><StatusBadge :status="item.status"/></article></section></LoadingRegion><AppDialog :open="Boolean(activeProject)" :title="`${activeProject?.name||''} · 项目用量`" wide @update:open="activeProject=$event?activeProject:null"><label>月份<input v-model="month" type="month" @change="activeProject&&showUsage(activeProject)"></label><LoadingRegion :initial-loading="usageLoadState.initialLoading.value" :refreshing="usageLoadState.refreshing.value" variant="list" label="正在加载项目用量"><template v-if="projectUsage"><div class="grid two"><div><h2>额度分配</h2><CreditDonut :segments="projectUsage.members.flatMap(member=>member.keys.map(key=>({name:`${member.user_name} · ${key.name}`,value:Number(key.allocation)}))).concat([{name:'可分配额度',value:Number(projectUsage.available)}])" :total="Number(projectUsage.quota)" label="项目额度分配"/><p>项目额度 {{projectUsage.quota}} · 已分配 {{projectUsage.allocated}} · 可分配 {{projectUsage.available}}</p></div><div><h2>实际开销</h2><CreditDonut :segments="projectUsage.members.map(member=>({name:member.user_name,value:Number(member.credits)})).concat([{name:'未消耗',value:Math.max(0,Number(projectUsage.quota)-Number(projectUsage.charged))}])" :total="Number(projectUsage.quota)" label="项目实际开销"/><p>已用 {{projectUsage.charged}} · 在途 {{projectUsage.pending}}</p></div></div><table class="usage-table"><thead><tr><th>成员</th><th>API Key 使用情况</th></tr></thead><tbody><tr v-for="member in projectUsage.members" :key="member.user_id"><td>{{member.user_name}}<br><span class="muted">共 {{member.credits}} credits</span></td><td><div v-for="key in member.keys" :key="key.id"><div class="row"><span>{{key.name}} · {{key.used}} / {{key.quota}}</span><strong>{{percentLabel(key.used,key.quota)}}</strong></div><div class="quota-progress"><span :style="{width:`${Math.min(100,percent(key.used,key.quota)??0)}%`}"/></div><div class="actions"><button v-if="key.status==='active'||key.status==='approved'" class="button ghost" @click="quotaKey={id:key.id,name:key.name,quota:key.quota};quota=key.quota;reason=''">调整额度</button><button v-if="key.status==='active'" class="button danger" @click="revokeKey={id:key.id,name:key.name};reason=''">撤销</button></div></div></td></tr></tbody></table></template></LoadingRegion></AppDialog><AppDialog :open="Boolean(quotaKey)" :title="`调整 ${quotaKey?.name||''} 月额度`" @update:open="quotaKey=$event?quotaKey:null"><label>新月额度（credits）<input v-model="quota" inputmode="decimal"></label><label>调额原因<textarea v-model="reason" rows="3" required/></label><button class="button primary" :disabled="!reason.trim()" @click="adjustQuota">确认调额</button></AppDialog><AppDialog :open="Boolean(revokeKey)" :title="`撤销 ${revokeKey?.name||''}`" @update:open="revokeKey=$event?revokeKey:null"><label>撤销原因<textarea v-model="reason" rows="3" required/></label><button class="button danger" :disabled="!reason.trim()" @click="revoke">确认撤销</button></AppDialog></section></template>
